import sys
from collections import Counter

H, W = map(int, sys.stdin.readline().split())
grid = [sys.stdin.readline().strip() for _ in range(H)]

sorted_strings = []
for row in grid:
    sorted_str = ''.join(sorted(row))
    sorted_strings.append(sorted_str)

freq = Counter(sorted_strings)

if H % 2 == 0:
    for count in freq.values():
        if count % 2 != 0:
            print("NO")
            sys.exit()
    print("YES")
else:
    odd_count = 0
    target_str = None
    for s, cnt in freq.items():
        if cnt % 2 == 1:
            odd_count += 1
            target_str = s
    if odd_count != 1:
        print("NO")
        sys.exit()
    cnt = Counter(target_str)
    odd_chars = 0
    for v in cnt.values():
        if v % 2 != 0:
            odd_chars += 1
    if odd_chars <= 1:
        print("YES")
    else:
        print("NO")
